function regexReplace(str) {
  let result = str;
  for (const [corrupted, fixed] of Object.entries(replacements)) {
    result = result.split(corrupted).join(fixed);
  }
  return result;
}

async function fixFinal() {
  console.log('Running final regex replacement on remaining 12 ContentBlocks and 3 SiteSettings...');
  
  const blocks = await prisma.contentBlock.findMany();
  let cbUpdates = [];
  for (const b of blocks) {
    let str = JSON.stringify(b.content);
    if (isCorrupted(str)) {
      let fixedStr = regexReplace(str);
      if (!isCorrupted(fixedStr)) {
        cbUpdates.push({ id: b.id, content: JSON.parse(fixedStr) });
      } else {
        console.log(`Failed to fix ContentBlock: ${b.id}`);
        // let's print what is left
        let match = fixedStr.match(/a\?\?|a\?\+|Ã|Â|\ufffd/g);
        console.log(`Still corrupted: ${match}`);
      }
    }
  }

  const settings = await prisma.siteSetting.findMany();
  let ssUpdates = [];
  for (const s of settings) {
    let str = JSON.stringify(s.value);
    if (isCorrupted(str)) {
      let fixedStr = regexReplace(str);
      if (!isCorrupted(fixedStr)) {
        ssUpdates.push({ id: s.id, value: JSON.parse(fixedStr) });
      } else {
        console.log(`Failed to fix SiteSetting: ${s.id}`);
      }
    }
  }

  if (cbUpdates.length > 0 || ssUpdates.length > 0) {
    console.log(`Ready to fix ${cbUpdates.length} blocks and ${ssUpdates.length} settings.`);
    await prisma.$transaction(async (tx) => {
      for (const update of cbUpdates) {
        await tx.contentBlock.update({ where: { id: update.id }, data: { content: update.content } });
      }
      for (const update of ssUpdates) {
        await tx.siteSetting.update({ where: { id: update.id }, data: { value: update.value } });
      }
    });
    console.log('Update completed successfully.');
  }

  console.log('\n--- POST-UPDATE VERIFICATION ---');
  const newContentBlocks = await prisma.contentBlock.findMany();
  let corruptedCbCount = 0;
  for (const block of newContentBlocks) {
    if (isCorrupted(JSON.stringify(block.content))) {
      corruptedCbCount++;
    }
  }
  
  const newSiteSettings = await prisma.siteSetting.findMany();
  let corruptedSsCount = 0;
  for (const setting of newSiteSettings) {
    if (isCorrupted(JSON.stringify(setting.value))) {
      corruptedSsCount++;
    }
  }

  const menuItemsCount = await prisma.menuItem.count();
  const pageNodesCount = await prisma.pageNode.count();

  console.log(`Corrupted ContentBlocks remaining: ${corruptedCbCount}`);
  console.log(`Corrupted SiteSettings remaining: ${corruptedSsCount}`);
  console.log(`Total MenuItems: ${menuItemsCount}`);
  console.log(`Total PageNodes: ${pageNodesCount}`);

  prisma.$disconnect();
}
fixFinal();
